-- challenge chal_quiz_aad_121 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_aad_121', (SELECT id FROM catalog.course WHERE public_id = 'ai-assisted-development'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-assisted-development') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aad-1-2' AND is_deleted = false LIMIT 1), 'spec-and-tests-first-quiz', 'What do the acceptance tests prove?', 'Two pieces of evidence from the second attempt at lesson bookmarks: the agent''s add() next to the acceptance tests it passed, and a test that was run against a stub before any code was written.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
