-- challenge chal_coding_aad_122 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_aad_122', (SELECT id FROM catalog.course WHERE public_id = 'ai-assisted-development'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-assisted-development') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aad-1-2' AND is_deleted = false LIMIT 1), 'bookmark-service-from-spec', 'Implement lesson bookmarks from a spec', 'CodeDev learners want to bookmark lessons and find them again on their dashboard. The first attempt was built by an agent from a one-line prompt and shipped with duplicate bookmarks, no limit and the oldest bookmark first. This time the spec came first. Implement the in-memory class BookmarkService(lessonIds) with three methods.

add(userId, lessonId, at) runs these checks in this order and returns the first that applies: (1) "invalid_request" when userId or lessonId is not a string with at least one non-space character, or at is not a finite number; (2) "lesson_not_found" when lessonId is not one of the catalog''s lessonIds (exact match, case-sensitive); (3) "already_bookmarked" when this user already has this lesson (nothing changes, the original time is kept); (4) "limit_reached" when the user already has 50 bookmarks; otherwise the bookmark is saved with time at and the result is "added".

remove(userId, lessonId) returns "invalid_request" for an invalid userId or lessonId (same rule), "removed" when the user had that bookmark (it is deleted), and "not_bookmarked" otherwise, also for a lesson that is not in the catalog. Removing twice is not an error.

list(userId) returns the user''s lesson ids, most recent first: larger at first; for the same at, the bookmark added later comes first. at is a time in milliseconds from the client and does not always increase (the mobile app syncs offline bookmarks late). A user with no bookmarks gets []. Limits and bookmarks are per user.

Input (stdin, read by the test runner): { "lessons": string[], "commands": [...] } where each command is { "op": "add", userId, lessonId, at }, { "op": "remove", userId, lessonId } or { "op": "list", userId }. All commands run in order on one service. Output: one JSON array with the result of every command (a string for add and remove, an array of lesson ids for list). Up to 1,000 commands, 120 lessons and 40 users per test; invalid input arrives as it would from a client (empty or blank strings, null, a number sent as a string). You may use an AI assistant: give it this spec and write the acceptance tests first. The hidden tests check every rule and how the rules interact.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
