INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_aad_212', (SELECT id FROM catalog.course WHERE public_id = 'ai-assisted-development'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-assisted-development') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aad-2-1' AND is_deleted = false LIMIT 1), 'diff-file-summary', 'Summarise a diff before you read it', 'A coding agent''s pull request on the CodeDev platform was approved as "a 20-line fix" to the progress bar, while the same diff deleted a database migration further down. The review bot now prints a summary of every file a diff touches before anyone reads the hunks. Write parseDiff(diff), which reads the text of one git diff (unified format, Git''s default options; paths never contain spaces) and returns one entry per file, in order: path (the path after the change; a deleted file keeps the path it had), from (the old path when the file was renamed, otherwise null), status ("added" when the header has "new file mode", "deleted" for "deleted file mode", "renamed" when the two paths in "diff --git a/<old> b/<new>" differ, otherwise "modified", which includes mode-only changes), binary (true when Git printed "Binary files ... differ"), and added / removed: the number of lines starting with "+" / "-" inside the file''s hunks (the lines after an "@@" header, until the next "diff --git" line). The "--- a/..." and "+++ b/..." header lines are not changes, but a changed line inside a hunk can itself start with "--", "++" or "diff --git". "\ No newline at end of file" and context lines (starting with a space) are not counted. Ignore any text before the first "diff --git" line; a text with none has no files. The test runner reads the diff from stdin and prints { files, totals } as JSON, with totals = { files, added, removed }.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
