    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_221'), '// src/lib/exp.ts
export const STREAK_BONUS_PERCENT = 10;
export function lessonExp(baseExp: number, streakDays: number): number {
  const bonus = streakDays >= 7 ? Math.round((baseExp * STREAK_BONUS_PERCENT) / 100) : 0;
  return baseExp + bonus;
}

// src/lib/exp.bonus.test.ts (Vitest), written by an AI assistant
import { vi, test, expect } from "vitest";
import { lessonExp } from "./exp";

vi.mock("./exp", () => ({ lessonExp: vi.fn(() => 11) }));

test("a 7-day streak gives the 10% bonus", () => {
  expect(lessonExp(10, 7)).toBe(11);
});

Statement: "If someone changes STREAK_BONUS_PERCENT from 10 to 100, this test fails, because lessonExp(10, 7) would then return 20."', 'single_choice'::question_type, 'False. vi.mock("./exp", factory) replaces the whole module for this test file (Vitest hoists the call above the imports), so the imported lessonExp is the mock, which returns 11 whatever the arguments and whatever exp.ts contains. The real function never runs: the test checks that the mock returns what the mock was told to return. Mock the collaborators of the code under test (a repository, a clock, an HTTP client), never the code under test itself. The quick check is mutation thinking: change the constant, run the test, and watch it stay green. The misconception is that a test named after a behaviour and calling a function with that name exercises the real code.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_221') AND order_index = 2)
    RETURNING id
)
