WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_231'), '// runs: the lengths of the runs of consecutive days, e.g. [3, 1, 5]
function longestStreak(runs: number[]): number {
  return Math.max(...runs);
}

// a new learner with no completions: runs is []
console.log(JSON.stringify({ longest: longestStreak([]) }));

Statement: "For a learner with no completions this prints {\"longest\":null}, because Math.max() with no arguments returns -Infinity and JSON.stringify writes -Infinity as null."', 'single_choice'::question_type, 'True. Math.max() with no arguments returns -Infinity (the identity value for a maximum), and the type number allows it, so tsc does not complain. JSON has no Infinity, so JSON.stringify writes -Infinity (and Infinity and NaN) as null. The profile API then sends longest: null to the page, which may show "null days" or crash on a call such as .toFixed(). The empty input is the first edge case to test, and the cheapest: start from an explicit value instead, for example runs.reduce((a, b) => Math.max(a, b), 0). Spreading has a second edge: with a very large array, Math.max(...runs) can throw a RangeError because every element becomes a function argument. The misconception is that a function that works for every non-empty example also works for none.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_231') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_aad_232 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_aad_232', (SELECT id FROM catalog.course WHERE public_id = 'ai-assisted-development'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-assisted-development') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aad-2-3' AND is_deleted = false LIMIT 1), 'learning-streaks', 'Learning streaks that survive time zones', 'The CodeDev profile page shows a learner''s current and longest learning streak: consecutive local calendar days with at least one completed lesson. The version an AI assistant wrote passed its demo and broke for learners in UTC+07:00, for learners who study twice a day and for learners who study late at night. Write computeStreaks(completedAt, offsetMinutes, now). completedAt: lesson-completion timestamps in ISO 8601 with an offset ("2026-10-21T06:30:00+07:00", "2026-10-20T23:30:00Z"), in any order, possibly several per day, never later than now; ignore any entry for which Date.parse returns NaN. offsetMinutes: the learner''s fixed UTC offset in minutes (420 = UTC+07:00, -300 = UTC-05:00, 330 = UTC+05:30; between -720 and 840; no daylight saving time). now: the current instant (ISO 8601, always valid). The local day of an instant is its calendar date at UTC + offsetMinutes; a day counts when at least one completion falls on it. Return { current, longest }: longest = the greatest number of consecutive counted days (0 when none), current = the length of the run of consecutive counted days that ends on the local day of now or the day before (the streak survives until the end of today), otherwise 0. Up to 5000 timestamps. Do not use Intl or the runner''s own time zone (getDate, getHours, toDateString): the offset is the only time zone. The test runner reads { cases: [{ completedAt, offsetMinutes, now }] } as JSON and prints one { current, longest } per case. You may use an AI assistant; the hidden tests check the edges.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aad_232');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aad_232'), 1, 'Before writing any loop: what is the "day" of a completion for a learner at UTC+07:00, and is it the same as the date you can read in the ISO string? Then list the inputs that would break a first version: none, two on one day, out of order, one minute either side of local midnight, and "not yet today".'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aad_232'), 2, 'Turn every valid timestamp into one integer, the learner''s local day number: take the instant from Date.parse, add the offset in milliseconds, and divide by the length of a day, rounding down. Whole day numbers make "consecutive" a comparison with previous + 1 - no months, no leap years. Put them in a Set, then sort the distinct day numbers before you walk them once.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aad_232'), 3, 'A similar trace with offset -300 (UTC-05:00): "2026-03-01T03:00:00Z" is 22:00 on 28 February local, "2026-03-01T14:00:00Z" is 09:00 on 1 March, "2026-03-03T01:00:00Z" is 20:00 on 2 March. Local days 28 Feb, 1 Mar, 2 Mar: one run of 3. With now = "2026-03-04T02:00:00Z" (21:00 on 3 March) the run ends yesterday, so it is still current; with now = "2026-03-05T05:00:00Z" (00:00 on 5 March) the last counted day is three days back and the current streak is 0, while the longest stays 3.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aad_232'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aad_232');
