+++ src/courses/search.repository.ts
+import { sanitize } from "sql-sanitize-lite";
+import { db } from "../db";
+
+export async function searchCourses(q: string, level?: string): Promise<CourseHit[]> {
+  const term = sanitize(q.trim());
+  let sql =
+    "SELECT id, title, level, status FROM courses " +
+    "WHERE title ILIKE ''%" + term + "%'' AND status = ''published''";
+  if (level) sql += " AND level = ''" + level + "''";
+  sql += " ORDER BY title, id LIMIT 20";
+  const { rows } = await db.query(sql);
+  return rows;
+}

Statement: "If searchCourses ignored q and returned the first 20 published courses for every search, the test in search.test.ts would fail."', 'single_choice'::question_type, 'False. The test only checks that the result is defined and is an array. A function that ignores q, returns every course, or returns [] for every search passes it just as well, so it cannot fail for any search behaviour that matters. A test is evidence only when some wrong implementation makes it fail: it should seed known courses and assert the exact titles that come back for a known q (and that drafts do not). The misconception is to count tests ("Tests added, all checks pass") instead of asking what each assertion would catch.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_311') AND order_index = 1)
    RETURNING id
