async function enrollWithPayment(req: EnrollRequest, deps: Deps): Promise<EnrollOutcome> {
  const enrollment = await deps.enrollments.insert({ userId: req.userId, courseId: req.courseId });
  const chargeId = await chargeLearner(req, enrollment.id, deps);
  await deps.enrollments.activate(enrollment.id, chargeId);
  try {
    await deps.mailer.sendReceipt(req.userId, req.courseId);
  } catch {
    // the receipt is not critical
  }
  return { status: "enrolled", enrollmentId: enrollment.id };
}

async function chargeLearner(req: EnrollRequest, enrollmentId: string, deps: Deps): Promise<string | null> {
  try {
    const charge = await deps.gateway.charge({ paymentMethodId: req.paymentMethodId,
      amountVnd: req.priceVnd, idempotencyKey: enrollmentId });
    return charge.chargeId;
  } catch (e) {
    return null;
  }
}

The gateway throws PaymentDeclinedError("insufficient_funds") for this learner''s card.

Statement: "The learner gets a payment error and no enrollment is stored."', 'single_choice'::question_type, 'False. chargeLearner catches the PaymentDeclinedError and returns null, so enrollWithPayment never sees a failure: it activates the enrollment with chargeId null and returns status "enrolled". The learner gets the course for free, and because the catch neither logs nor rethrows, nothing in the logs or the error tracker shows it - finance finds it a month later in reconciliation. A catch that turns an error into null or [] does not handle the error, it changes its meaning. The misconception is that wrapping a call in try/catch makes code safer; here it is what made the failure invisible.', 1, 5
