-- challenge chal_coding_aad_322 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_aad_322', (SELECT id FROM catalog.course WHERE public_id = 'ai-assisted-development'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-assisted-development') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aad-3-2' AND is_deleted = false LIMIT 1), 'swallowed-exceptions-failed-payment', 'Swallowed exceptions: the payment that failed silently', 'An AI coding assistant wrote the enrollment flow for premium courses on CodeDev from the request "create the enrollment, charge the learner''s payment method, activate the enrollment and email a receipt. Handle errors." Finance''s monthly reconciliation found 23 learners with an active premium enrollment and no captured payment, and the logs have no line about any of them.

Fix enrollWithPayment(req, deps):
- Insert the enrollment (it starts pending), charge req.paymentMethodId for req.priceVnd with the enrollment id as idempotencyKey, activate the enrollment with the charge id, then send the receipt.
- PaymentDeclinedError from the gateway: remove the enrollment, call logger.warn("payment_declined", context) with reason = the error''s code, and return { status: "payment_declined", code }.
- Any other error from the gateway: remove the enrollment, call logger.error("payment_failed", context) with reason = the error''s message, and throw the same error.
- The receipt email fails: the learner stays enrolled; call logger.warn("receipt_failed", context) with reason = the error''s message and return { status: "enrolled", enrollmentId }.
- DuplicateEnrollmentError from insert: let it propagate; nothing is charged.
Every log context is { enrollmentId, userId, courseId, reason }; log nothing on success.

The file contains an in-memory enrollments table, a fake gateway that behaves by payment method id (pm_ok..., pm_declined_<code>, pm_timeout, pm_broken), a mailer that bounces the users listed in the test, and a runner that processes the test''s requests in order and prints each outcome (or the error it threw), every log line, the remaining enrollment rows and the captured charges. Do not change the error classes, the types, the fakes or the runner.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
