VALUES ('chal_quiz_aad_411', (SELECT id FROM catalog.course WHERE public_id = 'ai-assisted-development'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-assisted-development') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aad-4-1' AND is_deleted = false LIMIT 1), 'ai-suggested-dependencies-quiz', 'Can you trust this dependency?', 'Two pieces of evidence from the Markdown comments pull request: an install that succeeded with a lookalike package, and a package name that returned 404.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_411');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_411');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_411'), 'The AI pull request added "dom-purify": "^3.1.0" to package.json. CI ran npm install:

added 1 package, and audited 912 packages in 4s
> dom-purify@3.1.0 postinstall
> node scripts/setup.js
found 0 vulnerabilities

package-lock.json now contains:
"node_modules/dom-purify": {
  "version": "3.1.0",
  "resolved": "https://registry.npmjs.org/dom-purify/-/dom-purify-3.1.0.tgz",
  "integrity": "sha512-Qm9..."
}

Registry snapshot: dom-purify, first published 2026-10-17, 212 weekly downloads; dompurify, first published 2014, about 9,000,000 weekly downloads.

Statement: "The install succeeded, npm audit found 0 vulnerabilities and the lockfile pins dom-purify with an integrity hash, so the dependency has been verified."', 'single_choice'::question_type, 'False. The integrity hash only proves that the next install gets the same bytes the registry served this time; it says nothing about whether those bytes are the package you meant. npm audit reports known advisories, and a package published nine days ago has none yet. The evidence that matters is elsewhere: the name differs from dompurify only by a hyphen, it is nine days old with 212 weekly downloads, and it runs a postinstall script during npm install. The common misconception is that a green install plus a lockfile means the dependency was checked; they make a bad choice reproducible, not safe.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_411') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_411'), 'The assistant wrote:

import { sanitize } from "isomorphic-purify";
// npm install isomorphic-purify

A reviewer checked the name:

$ npm view isomorphic-purify
npm error code E404
npm error 404 Not Found - GET https://registry.npmjs.org/isomorphic-purify - Not found

Asked again in a new chat with the same prompt, the assistant suggested isomorphic-purify a second time.

Statement: "Besides replacing the import with a package that exists, the team should treat the name isomorphic-purify as a risk, because anyone can publish a package under a name that returns 404 today."', 'single_choice'::question_type, 'True. A 404 means nobody has registered the name yet, not that nobody can. Package names on npm are first come, first served. A name that an assistant suggests repeatedly is exactly what slopsquatting attackers look for: they register it and wait for the next developer who copies the install command. Replacing the import fixes this pull request; blocking or flagging the name (a dependency check in CI, an allowlist) protects the next one. The misconception is that a 404 is harmless because the install simply fails.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_411') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_aad_412 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_aad_412', (SELECT id FROM catalog.course WHERE public_id = 'ai-assisted-development'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-assisted-development') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aad-4-1' AND is_deleted = false LIMIT 1), 'check-ai-suggested-dependencies', 'Check that suggested packages exist', 'An AI pull request for CodeDev''s Markdown comments added six dependencies: one returned 404, one imitated dompurify with a hyphen and ran a postinstall script, and one had been published six days earlier with 37 weekly downloads. Write checkDependencies(suggested, registry, policy, today), which checks every suggested { name, range } against a registry snapshot (registry[name] = { weeklyDownloads, versions: { "1.2.3": "YYYY-MM-DD" } }) and returns one { name, range, status, detail } per suggestion. The first check that applies decides the status: (1) "invalid" when the name is not 1-214 characters of a-z 0-9 @ / . _ ~ - or the range is not "*", "x.y.z", "^x.y.z" or "~x.y.z" (detail ""). A package is popular when it is in the registry with weeklyDownloads >= policy.popularWeeklyDownloads; checks 2-4 are skipped for a popular name. (2) "lookalike" when the name, found or not, is close to a popular name: remove every @ / . _ ~ - from both names and take the Levenshtein distance; close means <= 2, or <= 1 when the normalized popular name has 4 characters or fewer; detail = the popular name (smallest distance, then the name that sorts first). (3) "not_found" when the name is not in the registry (detail ""). (4) "new_low_downloads" when the age in whole days from the earliest publish date to today is < policy.newPackageDays and weeklyDownloads < policy.minWeeklyDownloads; detail "<age> days, <weeklyDownloads>/week". (5) "version_not_published" when no published version satisfies the range; detail = the highest published version. (6) "ok", detail = the highest version that satisfies the range. Versions are MAJOR.MINOR.PATCH compared as numbers; "*" any, "x.y.z" exact, "~x.y.z" at least x.y.z with the same major and minor, "^x.y.z" at least x.y.z with the same major (major 0: same major and minor). Sort the findings by status (lookalike, not_found, new_low_downloads, version_not_published, invalid, ok), then by name with < and >; equal status and name keep their input order. Dates are UTC; every registry package has at least one version. The runner reads { today, policy, registry, suggested } and prints the findings as JSON.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aad_412');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aad_412'), 1, 'For each suggestion, which question should be answered first: does this name look like something else, or does it exist? What does it mean for an attacker if a name close to lodash returns 404 today?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aad_412'), 2, 'Look at three helpers you need before the main loop: a normalize(name) that removes @ / . _ ~ -, a Levenshtein distance with one row of the dynamic-programming table at a time, and a version comparison that splits on "." and compares numbers, not strings. Then check the order of the six statuses, and where the age comes from: the earliest date among all versions, not the latest.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aad_412'), 3, 'A similar check on other names: popular names are chalk (normalized "chalk", 5 characters, so distance <= 2 counts) and qs (2 characters, so only distance 1). "chlak" -> distance 2 from chalk -> lookalike of chalk. "q_s" normalizes to "qs", distance 0 -> lookalike of qs. "chalk-cli" -> "chalkcli", distance 3 -> not a lookalike, so it goes on to the registry checks. For versions ["2.9.1", "2.10.0", "3.0.0"] and range "^2.9.0", the matches are 2.9.1 and 2.10.0, and the highest is 2.10.0.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aad_412'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
