-- challenge chal_quiz_aad_421 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_aad_421', (SELECT id FROM catalog.course WHERE public_id = 'ai-assisted-development'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-assisted-development') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aad-4-2' AND is_deleted = false LIMIT 1), 'secrets-in-prompts-quiz', 'Is this paste safe to send?', 'Two pieces of evidence from the leaked-key incident: a home-made redaction regex run on an error log, and the timeline after a key was pasted into a chat.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_421');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_421');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_421'), 'Before pasting logs into the assistant, a developer runs them through this function:

const redact = (text: string) =>
  text.replace(/(api[_-]?key|secret|token)\s*[:=]\s*\S+/gi, "$1=[REDACTED]");

The log being pasted:

10:41:07 POST /internal/leaderboard/refresh 500
  headers: { authorization: "Bearer FAKEopaqueAccessToken0123456789" }
  error: connect ECONNREFUSED postgres://codedev_app:Fake-Passw0rd!@db.codedev.test:5432/codedev
  config: { apiKey: "sk-codedev-FAKE-0000000000000000" }

Statement: "After redact(), the log can be pasted into the chat without exposing a credential."', 'single_choice'::question_type, 'False. The regex only knows three key names followed by : or =. It does replace the apiKey value (apiKey matches api[_-]?key, case-insensitive), but the authorization header is not one of its names, so the bearer token passes through, and the database password inside the connection string has no key name at all. Secrets show up by shape as well as by name: Bearer tokens, JWTs, connection strings with user:password@, private key blocks and well-known key prefixes need their own rules. The misconception is that a list of "secret-looking" variable names covers the secrets that appear in logs, headers and URLs.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_421') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_421'), 'Timeline from the incident review:

09:12  developer pastes .env.production into a chat with an AI assistant to ask why the leaderboard job fails;
       it contains OPENAI_API_KEY=sk-... and DATABASE_URL with the production password
09:20  developer notices, deletes the message and the conversation
09:25  developer writes in the team channel: "deleted it, we''re fine"

Statement: "Both credentials still have to be rotated (revoked and replaced), even though the conversation was deleted eight minutes later."', 'single_choice'::question_type, 'True. Once a secret has left your machine you cannot prove where it went: the text was sent to a third-party service, may sit in its logs or retention for some time under its policy, and may have been copied by browser extensions or synced devices. Deleting the conversation removes it from your view, not necessarily from every system that processed it. The only safe response is to treat the credentials as leaked: revoke and replace them, then check their usage logs for the time since 09:12. The misconception is that deleting the message undoes the leak.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_421') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_aad_422 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_aad_422', (SELECT id FROM catalog.course WHERE public_id = 'ai-assisted-development'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-assisted-development') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aad-4-2' AND is_deleted = false LIMIT 1), 'redact-secrets-before-prompting', 'Redact secrets before you paste', 'A CodeDev developer pasted a failing job''s log and the production .env into a chat with an AI assistant. Write redactSecrets(text, { redactEmails }), which returns { text, counts }: the text with secrets replaced by typed placeholders "[REDACTED:<type>]" and every other character unchanged (including \r\n line endings), and counts = the number of placeholders written per type. Apply these rules in order, each on the output of the previous one: (1) private_key: "-----BEGIN <words> PRIVATE KEY-----" (zero or more words of A-Z 0-9) up to and including the next "-----END <words> PRIVATE KEY-----", or to the end of the text when there is no END line; the whole block becomes the placeholder. (2) password: in "scheme://user:password@" (scheme = a letter then letters, digits, + . -; the user may be empty) replace only the password, the characters after the user''s ":" up to "@" with no whitespace, "/" or "@"; keep scheme, user and host. (3) jwt: "eyJ<c>.eyJ<c>.<c>" with <c> = one or more of A-Z a-z 0-9 _ -, not preceded by a letter, digit or _. (4) api_key: "sk-" + 20 or more of A-Z a-z 0-9 _ - (not preceded by A-Z a-z 0-9 _ -); "ghp_" + 20 or more of A-Z a-z 0-9 (not preceded by A-Z a-z 0-9 _); "AKIA" + exactly 16 of A-Z 0-9 (not preceded or followed by A-Z a-z 0-9). (5) bearer: "Bearer" in any case, whitespace, then a token of 16 or more of A-Z a-z 0-9 . _ ~ + / - plus any "=" padding; replace only the token. (6) env: a line "NAME=value" (optional leading spaces or tabs and "export ", NAME = A-Z then A-Z 0-9 _, spaces or tabs allowed around "=", value to the end of the line) whose NAME has an "_"-separated word SECRET, TOKEN, PASSWORD, PASSWD, PWD, KEY, APIKEY or CREDENTIALS: replace the whole value, unless it is empty or already contains "[REDACTED:". (7) email, only when redactEmails is true: local@domain, local = A-Z a-z 0-9 . _ % + -, domain = A-Z a-z 0-9 . - ending in "." and 2 or more letters. The runner reads { text, redactEmails } and prints { text, counts } as JSON. Every secret in the tests is fake.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aad_422');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aad_422'), 1, 'What happens to a JWT inside "Authorization: Bearer eyJ..." if the bearer rule runs before the jwt rule, and what happens to the line SESSION_TOKEN=eyJ... if the env rule runs first? Why does the order of the rules decide which placeholder a secret gets, and why must the text between secrets never change?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aad_422'), 2, 'Look at String.prototype.replace with a global regular expression and a replacement function: the function can increment a counter and return the placeholder, and its capture-group arguments let you keep part of a match (the URL before the password, the word Bearer, the NAME= part). For the key block, a lazy [\s\S]*? stops at the first END line; for the env lines, the m flag makes ^ and $ work per line, and . does not match \r, so a CRLF line keeps its \r.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aad_422'), 3, 'A similar redaction on different data: hide card numbers but keep the last 4 digits. text.replace(/\b(\d{4}[ -]?){3}(\d{4})\b/g, (_m, _g, last) => { count++; return "[CARD ****" + last + "]"; }) turns "paid with 4111 1111 1111 1234 at 10:02" into "paid with [CARD ****1234] at 10:02": one rule, one counter, one capture group kept, and every character outside the match untouched.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aad_422'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
