INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aad_422'), 'The incident paste: .env lines, a connection string and a JWT; the rest is unchanged', '{"text":"Leaderboard job fails after deploy, error and config below:\n\nError: password authentication failed for user \"codedev_app\"\n    at Pool.connect (node_modules/pg-pool/index.js:45:11)\n    at refreshLeaderboard (jobs/leaderboard.ts:18:22)\n\n# .env.production\nNODE_ENV=production\nDATABASE_URL=postgres://codedev_app:Fake-Passw0rd!@db.codedev.test:5432/codedev\nJWT_SECRET=FAKE-jwt-secret-for-the-course\nSESSION_TOKEN=eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiJ1c2VyXzQyIiwicm9sZSI6ImxlYXJuZXIifQ.ZmFrZS1zaWduYXR1cmUtZm9yLXRoZS1jb3Vyc2U\nLEADERBOARD_PAGE_SIZE=50","redactEmails":false}', '{"text":"Leaderboard job fails after deploy, error and config below:\n\nError: password authentication failed for user \"codedev_app\"\n    at Pool.connect (node_modules/pg-pool/index.js:45:11)\n    at refreshLeaderboard (jobs/leaderboard.ts:18:22)\n\n# .env.production\nNODE_ENV=production\nDATABASE_URL=postgres://codedev_app:[REDACTED:password]@db.codedev.test:5432/codedev\nJWT_SECRET=[REDACTED:env]\nSESSION_TOKEN=[REDACTED:jwt]\nLEADERBOARD_PAGE_SIZE=50","counts":{"private_key":0,"password":1,"jwt":1,"api_key":0,"bearer":0,"env":1,"email":0}}', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aad_422'), 'Bearer header, sk-/ghp_/AKIA keys and a private key block; emails kept with the flag off', '{"text":"curl -H \"Authorization: Bearer FAKEopaqueAccessToken0123456789\" https://api.codedev.test/leaderboard\nconst openai = new OpenAI({ apiKey: \"sk-codedev-FAKE-0000000000000000\" });\ngit clone https://ghp_FAKEcodedevEXAMPLE000000@github.com/codedev/platform.git\naws_access_key_id = AKIAIOSFODNN7EXAMPLE\nContact: support@codedev.test\ndeploy key:\n-----BEGIN RSA PRIVATE KEY-----\nTHIS-IS-A-FAKE-KEY-FOR-THE-CODEDEV-COURSE\nNOT-A-REAL-KEY-0000000000000000000000000\n-----END RSA PRIVATE KEY-----\nend of paste","redactEmails":false}', '{"text":"curl -H \"Authorization: Bearer [REDACTED:bearer]\" https://api.codedev.test/leaderboard\nconst openai = new OpenAI({ apiKey: \"[REDACTED:api_key]\" });\ngit clone https://[REDACTED:api_key]@github.com/codedev/platform.git\naws_access_key_id = [REDACTED:api_key]\nContact: support@codedev.test\ndeploy key:\n[REDACTED:private_key]\nend of paste","counts":{"private_key":1,"password":0,"jwt":0,"api_key":3,"bearer":1,"env":0,"email":0}}', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aad_422'), 'Emails are redacted only with the flag; a URL without a password is left alone', '{"text":"Reported by an.nguyen+qa@codedev.test and admin@mail.codedev.test.\nBearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiJhZG1pbl8xIiwicm9sZSI6ImFkbWluIn0.YW5vdGhlci1mYWtlLXNpZ25hdHVyZQ\nREDIS_URL=redis://cache.codedev.test:6379/0\nDocs: https://app.codedev.test/courses/42?ref=email\nOPENAI_API_KEY=\"sk-codedev-FAKE-0000000000000000\"","redactEmails":true}', '{"text":"Reported by [REDACTED:email] and [REDACTED:email].\nBearer [REDACTED:jwt]\nREDIS_URL=redis://cache.codedev.test:6379/0\nDocs: https://app.codedev.test/courses/42?ref=email\nOPENAI_API_KEY=\"[REDACTED:api_key]\"","counts":{"private_key":0,"password":0,"jwt":1,"api_key":1,"bearer":0,"env":0,"email":2}}', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aad_422'), 'Malformed and lookalike values are not secrets: short keys, prose, public keys, no dots', '{"text":"task-0123456789abcdefghijklmnop finished\nrisk-assessment-for-the-new-payment-flow.md\nBearer tokens are sent in the Authorization header.\nAuthorization: Bearer short\nsk-short ghp_tooShort AKIA123 AKIAIOSFODNN7EXAMPLEX\neyJhbGciOiJIUzI1NiJ9 is only a header, not a token\n-----BEGIN PUBLIC KEY-----\nFAKE-PUBLIC-KEY-DATA\n-----END PUBLIC KEY-----\nconst token = getToken(req)\nPASSWORD_MIN_LENGTH=\nWrite to me at learner(at)codedev.test","redactEmails":false}', '{"text":"task-0123456789abcdefghijklmnop finished\nrisk-assessment-for-the-new-payment-flow.md\nBearer tokens are sent in the Authorization header.\nAuthorization: Bearer short\nsk-short ghp_tooShort AKIA123 AKIAIOSFODNN7EXAMPLEX\neyJhbGciOiJIUzI1NiJ9 is only a header, not a token\n-----BEGIN PUBLIC KEY-----\nFAKE-PUBLIC-KEY-DATA\n-----END PUBLIC KEY-----\nconst token = getToken(req)\nPASSWORD_MIN_LENGTH=\nWrite to me at learner(at)codedev.test","counts":{"private_key":0,"password":0,"jwt":0,"api_key":0,"bearer":0,"env":0,"email":0}}', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aad_422'), 'CRLF endings, export prefix, spaces around =, quoted and empty values stay byte-identical', '{"text":"export STRIPE_SECRET_KEY=FAKE_stripe_key_for_course\r\n  GITHUB_TOKEN = FAKE-token-with-spaces\r\nSANITY_API_TOKEN=''FAKE-sanity-token''\r\nMAIL_PASSWORD=\r\nNEXT_PUBLIC_APP_URL=https://app.codedev.test\r\nTOKENIZER_MODEL=cl100k_base\r\nDB_PASSWORD_URL=postgres://u:FakePw@db.codedev.test/x\r\n","redactEmails":false}', '{"text":"export STRIPE_SECRET_KEY=[REDACTED:env]\r\n  GITHUB_TOKEN = [REDACTED:env]\r\nSANITY_API_TOKEN=[REDACTED:env]\r\nMAIL_PASSWORD=\r\nNEXT_PUBLIC_APP_URL=https://app.codedev.test\r\nTOKENIZER_MODEL=cl100k_base\r\nDB_PASSWORD_URL=postgres://u:[REDACTED:password]@db.codedev.test/x\r\n","counts":{"private_key":0,"password":1,"jwt":0,"api_key":0,"bearer":0,"env":3,"email":0}}', 3, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aad_422'), 'Two key blocks, a key with no END line, and redis://:password@ URLs', '{"text":"first:\n-----BEGIN OPENSSH PRIVATE KEY-----\nFAKE-OPENSSH-KEY-FOR-THE-COURSE-000000000\n-----END OPENSSH PRIVATE KEY-----\nbetween the keys\n-----BEGIN RSA PRIVATE KEY-----\nTHIS-IS-A-FAKE-KEY-FOR-THE-CODEDEV-COURSE\nNOT-A-REAL-KEY-0000000000000000000000000\n-----END RSA PRIVATE KEY-----\ncache: redis://:FAKE-redis-pass@cache.codedev.test:6379\nreplica: rediss://default:FAKE-pass2@replica.codedev.test:6380\ntruncated paste:\n-----BEGIN PRIVATE KEY-----\nFAKE-TRUNCATED-KEY-0000\nAKIAIOSFODNN7EXAMPLE would be here too","redactEmails":true}', '{"text":"first:\n[REDACTED:private_key]\nbetween the keys\n[REDACTED:private_key]\ncache: redis://:[REDACTED:password]@cache.codedev.test:6379\nreplica: rediss://default:[REDACTED:password]@replica.codedev.test:6380\ntruncated paste:\n[REDACTED:private_key]","counts":{"private_key":3,"password":2,"jwt":0,"api_key":0,"bearer":0,"env":0,"email":0}}', 3, false, true, 6),
