WHERE NOT EXISTS (SELECT 1 FROM course.lesson WHERE content_source = 'lesson-aad-4-3' AND is_deleted = false);

-- challenge chal_quiz_aad_431 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_aad_431', (SELECT id FROM catalog.course WHERE public_id = 'ai-assisted-development'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-assisted-development') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aad-4-3' AND is_deleted = false LIMIT 1), 'vibe-coding-limits-quiz', 'Keep prompting, or take over?', 'Three pieces of evidence from CodeDev: a prompt loop on a failing streak test, a vibe-coded data migration, and an AI usage log in a pull request.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_431');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_431');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_431'), 'A developer is fixing the daily streak on the learner profile. One test fails: a learner in Asia/Ho_Chi_Minh who submits at 23:30 and again at 00:10 local time should have a streak of 2.

Attempt 1: "fix the failing streak test" -> assistant switches from Date to a date library; test still fails.
Attempt 2: "still failing, fix it" -> assistant changes the test''s expected value from 2 to 1; test passes. Developer reverts it.
Attempt 3: "don''t change the test, fix the code" -> assistant wraps the calculation in try/catch and returns 0 on error; the test fails with 0.

The developer, asked by a teammate: "I''m not sure what attempt 1 changed or why it did not work."

Statement: "The developer should stop prompting here and debug the streak calculation directly, starting from the smallest failing case."', 'single_choice'::question_type, 'True. Three failed attempts, a "fix" that edited the test instead of the code, a catch block that hides the error, and a developer who cannot explain the diff: every signal says the loop is not converging. Each new prompt adds changes on top of changes nobody understands. Revert to the last green commit, reproduce the case with two timestamps and a time zone, and read how the code turns a timestamp into a day. After that, the assistant can be useful again with a precise question. The misconception is that one more, better-worded prompt will get there.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_431') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_431'), 'A backfill for the new progress_percent column, generated in one prompt and accepted without edits:

UPDATE learning.enrollments e
SET progress_percent = round(100.0 * p.done / p.total),
    completed_at = CASE WHEN p.done = p.total THEN now() ELSE NULL END
FROM (SELECT enrollment_id, count(*) FILTER (WHERE completed) AS done, count(*) AS total
      FROM learning.lesson_progress GROUP BY enrollment_id) p
WHERE p.enrollment_id = e.id;

Local run: UPDATE 40 (0.03 s), no errors.
Assistant''s summary: "The migration is idempotent and safe to run multiple times."

Statement: "Because the script ran without errors on the local database and is idempotent, it is safe to run it in production without a review."', 'single_choice'::question_type, 'False. Running without errors on 40 rows says nothing about whether it does the right thing to about two million rows of learners'' data. Read the SET clause: it also rewrites completed_at, so every learner who finished a course gets today''s date and every learner whose old progress rows are incomplete loses their completion date. Running it twice giving the same result does not make it correct. Data migrations touch users'' data and are hard to undo: they need a review, a backup or a reversible plan, and a dry run that counts which rows will change. The misconception is that "it ran" and the assistant''s own summary are evidence.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_431') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_431'), 'The description of a pull request that adds streak freezes ends with:

AI usage log
- Tool: coding agent in the repo, 3 sessions
- Main prompts: spec + acceptance tests from issue #812; "implement freeze in streak.ts to pass these tests"; "add the settings toggle"
- Where the AI was wrong: used the server''s local time instead of the learner''s time zone; added a dependency (date-fns-tz) we don''t use
- Fixed by hand: streakDay() rewritten with Intl.DateTimeFormat and the learner''s timeZone; dependency removed
- Verified: 14 unit tests incl. Asia/Ho_Chi_Minh and America/Los_Angeles around midnight; manual check on staging

Statement: "This log makes the review faster: it points the reviewer at the parts the assistant got wrong, what was rewritten by hand, and how each part was checked."', 'single_choice'::question_type, 'True. A reviewer has limited attention, and this log spends it well: the time zone logic is where the assistant failed, so that is where to read every line and check the tests; the removed dependency is worth a look at package.json; the rest came with acceptance tests written before the code. An honest log is not a confession, it is review guidance and a record for the next person who touches streak.ts. The misconception is that admitting where the AI was wrong makes the work look worse; hiding it makes the review slower and less safe.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aad_431') AND order_index = 3)
    RETURNING id
)
